dark.customCSS:
:root {
	--rp-glass: color-mix(in oklab, var(--color-gray-850) 80%, transparent);
	--rp-sidebar: color-mix(in oklab, var(--color-gray-850) 92%, transparent);
	--rp-bubble: var(--color-gray-800);
	--rp-selected: color-mix(in oklab, var(--color-gray-700) 70%, transparent);
	--rp-line: color-mix(in oklab, var(--color-gray-600) 60%, transparent);
	--rp-shade: color-mix(in oklab, black 60%, transparent);
	--rp-text: var(--color-gray-100);
	--rp-heading: #c4a7e7;
	--rp-link: #9ccfd8;
	--rp-quote: #ebbcba;
	--rp-focus: color-mix(in oklab, #c4a7e7 70%, transparent);
	--rp-ring: color-mix(in oklab, #c4a7e7 22%, transparent);
	--rp-mark: var(--color-gray-700);
}

/* Rosé Pine: base, surface and overlay come from the palette steps; the
   accents (iris, foam, pine, rose, love) mark headings, links and focus. */
#message-input-container {
	background-color: var(--rp-glass) !important;
	border-color: var(--rp-line) !important;
	backdrop-filter: blur(12px);
	box-shadow: 0 10px 30px -18px var(--rp-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--rp-focus) !important;
	box-shadow: 0 0 0 3px var(--rp-ring), 0 10px 30px -18px var(--rp-shade);
}
.chat-user .rounded-3xl { background-color: var(--rp-bubble) !important; }
#sidebar {
	background-color: var(--rp-sidebar) !important;
	border-inline-end: 1px solid var(--rp-line);
}
#sidebar-chat-item.selected { background-color: var(--rp-selected); }
.markdown-prose { color: var(--rp-text); }
.markdown-prose strong { color: var(--rp-text); }
.markdown-prose :is(h1, h2, h3, h4) { color: var(--rp-heading); }
.markdown-prose a { color: var(--rp-link); text-decoration-color: color-mix(in oklab, var(--rp-link) 45%, transparent); }
.markdown-prose blockquote { border-inline-start-color: var(--rp-quote); }
.markdown-prose hr { border-color: var(--rp-line); }
html { scrollbar-color: var(--rp-line) transparent; }
::selection { background-color: var(--rp-mark); }

